import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 71 A famous clock","description":"学习 非真实条件句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 71 A famous clock","description":"学习 非真实条件句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 非真实条件句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 70 Red for danger","link":"/life/english/new-concept/book-2/unit-03/lesson-070"},"next":{"text":"第二册：实践与进步 · Lesson 72 A car called Bluebird","link":"/life/english/new-concept/book-2/unit-03/lesson-072"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 70 Red for danger","link":"/life/english/new-concept/book-2/unit-03/lesson-070"},"next":{"text":"第二册：实践与进步 · Lesson 72 A car called Bluebird","link":"/life/english/new-concept/book-2/unit-03/lesson-072"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-071.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-071.md"}'),l={name:"life/english/new-concept/book-2/unit-03/lesson-071.md"};function i(r,e,s,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-71-a-famous-clock" tabindex="-1">第二册：实践与进步 · Lesson 71 A famous clock <a class="header-anchor" href="#第二册-实践与进步-·-lesson-71-a-famous-clock" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 71 A famous clock&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>城市大钟的建造与保存涉及历史条件，假设不同历史要清楚标明未发生；练习过去虚拟。本课的语言观察是：had not been repaired 是过去反事实的被动条件；would have stopped 是假设结果。否定条件不表示实际没有维修，恰恰在此暗示修过。完成学习后，请写一个历史设施得到维护的故事，再补一句未维护的假设后果。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>clock</td><td>/klɒk/</td><td>n.</td><td>钟</td><td>a station clock</td></tr><tr><td>parliament</td><td>/ˈpɑːləmənt/</td><td>n.</td><td>议会</td><td>a parliament building</td></tr><tr><td>tower</td><td>/ˈtaʊə/</td><td>n.</td><td>塔</td><td>a clock tower</td></tr><tr><td>historic</td><td>/hɪˈstɒrɪk/</td><td>adj.</td><td>具有历史意义的</td><td>a historic building</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>strike the hour — 整点报时</li><li>keep time — 走时准确、计时</li></ul><h2 id="语法讲解-非真实条件句" tabindex="-1">语法讲解：非真实条件句 <a class="header-anchor" href="#语法讲解-非真实条件句" aria-label="Permalink to &quot;语法讲解：非真实条件句&quot;">​</a></h2><p>与现在事实不同或可能性较小的假设常用 if 加过去式，主句用 would/could 加原形；与过去事实相反则用 if 加 had done，主句用 would/could have done。这里的过去形式主要表达距离感，不总指过去时间。be 在正式假设中可用 were。选择句型前先确定假设发生的时间，再检查结果的时间，不要把真实未来条件与虚拟假设混用。本课应用：had not been repaired 是过去反事实的被动条件；would have stopped 是假设结果。否定条件不表示实际没有维修，恰恰在此暗示修过。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>If the clock had not been repaired, it would have stopped that winter.</p></blockquote><p>如果那座钟没有修过，它在那个冬天就会停摆。</p><p>if 从句 had not been repaired 为过去完成被动；主句 would have stopped 表未发生的过去结果。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>would stopped 缺少 have；过去反事实结果要用 would have stopped。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读出 had not been，not 是关键信息；比较 strike 与 struck 的元音。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>If the clock had not been repaired, it would have stopped that winter. The town paid for the work in autumn. It still rings every evening.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一个历史设施得到维护的故事，再补一句未维护的假设后果。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：if 从句 had not been repaired 为过去完成被动；主句 would have stopped 表未发生的过去结果。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：would stopped 缺少 have；过去反事实结果要用 would have stopped。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补全：It would ___ stopped without repairs.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 过去假设结果结构为 would have done。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>维修费用在什么季节支付？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> In autumn.</p><p><strong>解析：</strong> 示范说明秋天付费，冬天属于假设中的结果时间。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>这句话暗示钟实际修过还是没修过？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 修过。</p><p><strong>解析：</strong> 对过去“如果没修”的反事实设想，与实际维修相反。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：非真实条件句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-070">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-072">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(l,[["render",i]]);export{u as __pageData,b as default};
